CREATE TABLE units (
            unit_id   INTEGER PRIMARY KEY AUTOINCREMENT,
            code      TEXT NOT NULL,
            name      TEXT NOT NULL DEFAULT '',
            active    INTEGER NOT NULL DEFAULT 1
        );

CREATE TABLE equipment (
            equipment_id        INTEGER PRIMARY KEY AUTOINCREMENT,
            property_tag        TEXT NOT NULL DEFAULT '',
            equip_class         TEXT NOT NULL DEFAULT 'instrument',
            name                TEXT NOT NULL,
            manufacturer        TEXT NOT NULL DEFAULT '',
            model               TEXT NOT NULL DEFAULT '',
            location            TEXT NOT NULL DEFAULT '',
            rate                REAL NOT NULL DEFAULT 0,
            rate_unit           TEXT NOT NULL DEFAULT 'per sample',
            rate_effective_date DATE,
            receiving_subaccount TEXT NOT NULL DEFAULT '',
            contact_person      TEXT NOT NULL DEFAULT '',
            active              INTEGER NOT NULL DEFAULT 1,
            created_at          TEXT NOT NULL
        , status TEXT NOT NULL DEFAULT 'available', status_note TEXT NOT NULL DEFAULT '', status_since TEXT, service_due_date DATE, lab_id INTEGER REFERENCES labs(lab_id));

CREATE TABLE picklists (
            picklist_id INTEGER PRIMARY KEY AUTOINCREMENT,
            list_key    TEXT NOT NULL,
            code        TEXT NOT NULL,
            label       TEXT NOT NULL,
            sort_order  INTEGER NOT NULL DEFAULT 100,
            active      INTEGER NOT NULL DEFAULT 1,
            protected   INTEGER NOT NULL DEFAULT 0,
            UNIQUE (list_key, code)
        );

CREATE TABLE export_batches (
            batch_id     INTEGER PRIMARY KEY AUTOINCREMENT,
            period_start DATE NOT NULL,
            period_end   DATE NOT NULL,
            generated_at TEXT NOT NULL,
            generated_by TEXT NOT NULL DEFAULT '',
            record_count INTEGER NOT NULL DEFAULT 0,
            total_amount REAL NOT NULL DEFAULT 0,
            reopened     INTEGER NOT NULL DEFAULT 0
        , lab_id INTEGER REFERENCES labs(lab_id));

CREATE TABLE usage_records (
            usage_id             INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_id         INTEGER NOT NULL REFERENCES equipment(equipment_id),
            grant_id             INTEGER NOT NULL REFERENCES grants(grant_id),
            operator_name        TEXT NOT NULL DEFAULT '',
            use_date             DATE NOT NULL,
            sample_count         INTEGER NOT NULL DEFAULT 1,
            rate_charged         REAL NOT NULL DEFAULT 0,
            rate_unit_charged    TEXT NOT NULL DEFAULT '',
            receiving_subaccount TEXT NOT NULL DEFAULT '',
            total_charge         REAL NOT NULL DEFAULT 0,
            batch_identifier     TEXT NOT NULL DEFAULT '',
            notes                TEXT NOT NULL DEFAULT '',
            exported             INTEGER NOT NULL DEFAULT 0,
            export_batch_id      INTEGER REFERENCES export_batches(batch_id),
            voided               INTEGER NOT NULL DEFAULT 0,
            void_reason          TEXT NOT NULL DEFAULT '',
            created_at           TEXT NOT NULL
        );

CREATE TABLE reservations (
            reservation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_id   INTEGER NOT NULL REFERENCES equipment(equipment_id),
            reserved_by    TEXT NOT NULL DEFAULT '',
            start_datetime TEXT NOT NULL,
            end_datetime   TEXT NOT NULL,
            purpose        TEXT NOT NULL DEFAULT '',
            usage_id       INTEGER REFERENCES usage_records(usage_id),
            created_at     TEXT NOT NULL
        );

CREATE TABLE admin_users (
            user_id       INTEGER PRIMARY KEY AUTOINCREMENT,
            username      TEXT NOT NULL UNIQUE,
            password_hash TEXT NOT NULL,
            display_name  TEXT NOT NULL DEFAULT '',
            active        INTEGER NOT NULL DEFAULT 1,
            created_at    TEXT NOT NULL,
            last_login    TEXT
        , may_edit_code INTEGER NOT NULL DEFAULT 0);

CREATE TABLE settings (
            "key"  TEXT PRIMARY KEY,
            value  TEXT NOT NULL DEFAULT ''
        );

CREATE TABLE login_attempts (
            attempt_id   INTEGER PRIMARY KEY AUTOINCREMENT,
            ip           TEXT NOT NULL DEFAULT '',
            username     TEXT NOT NULL DEFAULT '',
            succeeded    INTEGER NOT NULL DEFAULT 0,
            attempted_at TEXT NOT NULL
        );

CREATE INDEX idx_reservations_equipment_start ON reservations (equipment_id, start_datetime);

CREATE INDEX idx_reservations_equipment_end   ON reservations (equipment_id, end_datetime);

CREATE INDEX idx_usage_use_date   ON usage_records (use_date);

CREATE INDEX idx_usage_exported   ON usage_records (exported, voided);

CREATE INDEX idx_usage_grant      ON usage_records (grant_id);

CREATE INDEX idx_usage_equipment  ON usage_records (equipment_id);

CREATE INDEX idx_attempts_time    ON login_attempts (attempted_at);

CREATE UNIQUE INDEX idx_equipment_tag ON equipment (property_tag) WHERE property_tag <> '';

CREATE TABLE equipment_costs (
  cost_id INTEGER PRIMARY KEY AUTOINCREMENT,
  equipment_id INTEGER NOT NULL REFERENCES equipment(equipment_id),
  cost_date DATE NOT NULL, category TEXT NOT NULL DEFAULT 'consumable',
  description TEXT NOT NULL DEFAULT '', vendor TEXT NOT NULL DEFAULT '',
  amount REAL NOT NULL DEFAULT 0, paid_from_cfopa TEXT NOT NULL DEFAULT '',
  reference TEXT NOT NULL DEFAULT '', covers_start DATE, covers_end DATE,
  notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, created_by TEXT NOT NULL DEFAULT '');

CREATE INDEX idx_costs_equipment ON equipment_costs (equipment_id, cost_date);

CREATE TABLE email_log (
  email_id INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL DEFAULT '',
  purpose TEXT NOT NULL DEFAULT '', to_address TEXT NOT NULL DEFAULT '',
  cc_address TEXT NOT NULL DEFAULT '', subject TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '', equipment_id INTEGER REFERENCES equipment(equipment_id),
  opened_at TEXT, status TEXT NOT NULL DEFAULT 'composed', lab_id INTEGER REFERENCES labs(lab_id));

CREATE INDEX idx_email_log_time ON email_log (created_at DESC);

CREATE TABLE labs (
  lab_id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '', unit_id INTEGER REFERENCES units(unit_id),
  lab_group_name TEXT NOT NULL DEFAULT '', lab_group_email TEXT NOT NULL DEFAULT '',
  equipment_contact_name TEXT NOT NULL DEFAULT '', equipment_contact_email TEXT NOT NULL DEFAULT '',
  equipment_contact_cc TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);

CREATE TABLE lab_members (
  member_id INTEGER PRIMARY KEY AUTOINCREMENT, lab_id INTEGER NOT NULL REFERENCES labs(lab_id),
  person_key TEXT NOT NULL, display_name TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL,
  UNIQUE (lab_id, person_key));

CREATE INDEX idx_lab_members_key ON lab_members (person_key);

CREATE INDEX idx_equipment_lab ON equipment (lab_id, active);

CREATE TABLE "grants" (
    grant_id INTEGER PRIMARY KEY AUTOINCREMENT,
    lab_id INTEGER NOT NULL REFERENCES labs(lab_id),
    cfopa TEXT NOT NULL, cfopa_base TEXT NOT NULL DEFAULT '', activity_code TEXT NOT NULL DEFAULT 'A00',
    title TEXT NOT NULL DEFAULT '', display_label TEXT NOT NULL DEFAULT '',
    principal_investigator TEXT NOT NULL DEFAULT '', unit_id INTEGER REFERENCES units(unit_id),
    start_date DATE, end_date DATE, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);

CREATE UNIQUE INDEX idx_grants_lab_cfopa ON grants (lab_id, cfopa);

CREATE INDEX idx_grants_base ON grants (cfopa_base);

